"""Render the already computed primary ratios without fitting or reanalysis."""

import argparse
import hashlib
import json
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D


SOURCE_SHA256 = "ba79dee70320b9e11d1aba149311702ab898e2c95acf8d32c7b75b8badfeacd5"
HERE = Path(__file__).resolve().parent
ROWS = (
    ("fanout", "ordinary", "Fanout\nDirect / ordinary"),
    ("shared-tail", "ordinary", "Shared-tail\nDirect / ordinary"),
    ("fanout", "dense", "Fanout\nDirect / dense"),
    ("shared-tail", "dense", "Shared-tail\nDirect / dense"),
)
PANELS = (
    ("totalNs", "Total query latency", (0.60, 1.06), (0.6, 0.7, 0.8, 0.9, 1.0)),
    ("allThreadAllocatedBytes", "All-thread allocation", (0.82, 1.03), (0.85, 0.9, 0.95, 1.0)),
)


def sha256(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", type=Path, default=HERE.parent / "independent-v2/independent-results.json")
    parser.add_argument("--output-dir", type=Path, default=HERE)
    args = parser.parse_args()
    raw = args.input.read_bytes()
    if hashlib.sha256(raw).hexdigest() != SOURCE_SHA256:
        raise ValueError("The source is not the accepted independent comparison-v2 result.")
    result = json.loads(raw)
    if not result["valid"] or not result["complete"]:
        raise ValueError("The source cohort is incomplete or unqualified.")
    comparisons = {
        (entry["fixture"], entry["denominator"]): entry
        for entry in result["comparisons"]
        if entry["numerator"] == "direct"
    }

    plt.rcParams.update({
        "font.family": "DejaVu Sans",
        "font.size": 10,
        "axes.spines.top": False,
        "axes.spines.right": False,
        "axes.spines.left": False,
        "axes.edgecolor": "#A8AFB8",
        "axes.labelcolor": "#26313D",
        "xtick.color": "#52606E",
        "ytick.color": "#26313D",
        "svg.fonttype": "none",
        "svg.hashsalt": "direct-memo-comparison-v2-paired-ratios",
        "savefig.facecolor": "white",
    })
    point_color = "#245C83"
    median_color = "#B34B14"
    range_color = "#7595AB"
    fig, axes = plt.subplots(1, 2, figsize=(12, 6), sharey=True)
    fig.subplots_adjust(left=0.155, right=0.975, bottom=0.27, top=0.73, wspace=0.14)
    fig.suptitle("Direct value memo: paired latency and allocation", x=0.155, y=0.965,
                 ha="left", fontsize=17, fontweight="bold", color="#142C3E")
    fig.text(0.155, 0.914, "Six paired process ratios per comparison  ·  Lower favors direct reuse",
             ha="left", fontsize=11, color="#52606E")

    handles = [
        Line2D([], [], linestyle="none", marker="o", markersize=5, color=point_color,
               label="Individual paired ratio"),
        Line2D([], [], linestyle="none", marker="D", markersize=6, color=median_color,
               label="Median"),
        Line2D([], [], color=range_color, linewidth=1.4, marker="|", markersize=7,
               label="Observed min–max"),
        Line2D([], [], color="#6F7781", linestyle=(0, (4, 3)), linewidth=1.1,
               label="1.0 = equal cost"),
    ]
    fig.legend(handles=handles, loc="upper left", bbox_to_anchor=(0.149, 0.865),
               ncol=4, frameon=False, fontsize=9, handlelength=1.8, columnspacing=1.9)

    plotted = []
    offsets = (-0.34, -0.23, -0.12, 0.12, 0.23, 0.34)
    for ax, (metric, title, limits, ticks) in zip(axes, PANELS, strict=True):
        ax.set_title(title, loc="left", fontsize=12, fontweight="bold", pad=14, color="#142C3E")
        ax.set_xlim(*limits)
        ax.set_xticks(ticks)
        ax.set_ylim(-0.5, 3.7)
        ax.set_axisbelow(True)
        ax.grid(axis="x", color="#E8ECF0", linewidth=0.8)
        ax.axvline(1.0, color="#6F7781", linewidth=1.1, linestyle=(0, (4, 3)), zorder=1)
        ax.tick_params(axis="y", length=0, pad=12)
        ax.set_xlabel("Direct / comparator", labelpad=10)
        for index, (fixture, comparator, _) in enumerate(ROWS):
            entry = comparisons[fixture, comparator]
            points = entry["perRound"]
            if [item["round"] for item in points] != list(range(6)):
                raise ValueError("Expected all six prescribed rounds, in their original order.")
            values = [item["ratios"][metric] for item in points]
            median = entry["medianRatios"][metric]
            lo, hi = entry["ratioRanges"][metric]
            y = 3 - index
            ax.hlines(y, lo, hi, color=range_color, linewidth=1.6, zorder=2)
            ax.vlines((lo, hi), y - 0.09, y + 0.09, color=range_color, linewidth=1.2, zorder=2)
            ax.scatter(values, [y + offset for offset in offsets], color=point_color,
                       s=18, linewidths=0.55, edgecolors="white", zorder=3)
            ax.scatter([median], [y], color=median_color, marker="D", s=42,
                       linewidths=0.75, edgecolors="white", zorder=4)
            ax.text(0.985, y + 0.50, f"median {median:.6f}",
                    transform=ax.get_yaxis_transform(), ha="right", va="center",
                    fontsize=8.6, color=median_color)
            plotted.append({"fixture": fixture, "comparator": comparator, "metric": metric,
                            "sixPairedRatiosInRoundOrder": values, "median": median,
                            "observedRange": [lo, hi]})

    axes[0].set_yticks((3, 2, 1, 0), labels=[row[2] for row in ROWS], fontsize=10)
    fig.text(0.155, 0.14, "Dots are vertically offset by round for visibility. Whiskers show the full observed range, not confidence intervals.",
             ha="left", fontsize=9, color="#52606E")
    fig.text(0.155, 0.103, "Each process ratio uses its median of five measured queries; all six paired ratios are retained.",
             ha="left", fontsize=9, color="#52606E")
    fig.text(0.155, 0.066, "Allocation does not measure retained heap. The memo’s array-only ledger charge does not bound retained Values.",
             ha="left", fontsize=9, color="#52606E")
    fig.text(0.155, 0.025, "Source: independently validated comparison-v2  ·  36 JVMs / 180 measurements  ·  No historical or interrupted runs pooled",
             ha="left", fontsize=8, color="#667582")

    args.output_dir.mkdir(parents=True, exist_ok=True)
    stem = args.output_dir / "direct-memo-paired-ratios"
    fig.savefig(stem.with_suffix(".svg"), metadata={"Date": None,
                "Description": "Six paired process ratios per comparison; observed ranges are not confidence intervals."})
    fig.savefig(stem.with_suffix(".png"), dpi=200,
                metadata={"Description": "Six paired process ratios; medians and observed min-max, not confidence intervals."})
    plt.close(fig)
    receipt = {
        "format": 1,
        "sourceFile": str(args.input.resolve()),
        "sourceSha256": SOURCE_SHA256,
        "plotScriptFile": str(Path(__file__).resolve()),
        "plotScriptSha256": sha256(__file__),
        "computation": "Only plots existing per-round ratios, medians, and ranges; no fitting or new analysis.",
        "plottedValues": plotted,
        "outputs": {path.name: {"bytes": path.stat().st_size, "sha256": sha256(path)}
                    for path in (stem.with_suffix(".svg"), stem.with_suffix(".png"))},
    }
    stem.with_suffix(".json").write_text(json.dumps(receipt, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"figure": str(stem), "panels": 2, "comparisons": 4,
                      "pairedPointsPerPanel": 24, "sourceSha256": SOURCE_SHA256}))


if __name__ == "__main__":
    main()
